'use strict';
const D=window.RADAR, app=document.querySelector('#app');
const esc=s=>String(s??'Unreported').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>'$'+n.toLocaleString('en-US'), compact=n=>'$'+(n>=1e9?(n/1e9).toFixed(2)+'B':(n/1e6).toFixed(2)+'M');
const num=(n,d=2)=>n===null?'—':n.toLocaleString('en-US',{maximumFractionDigits:d,minimumFractionDigits:d});
const watch=new Set(D.watchlist), categories=[...new Set(D.rows.map(r=>r.category??'Uncategorized'))].sort(),chains=[...new Set(D.rows.flatMap(r=>r.chains))].sort();
let state={q:'',cat:'',chain:'',band:'',watch:false,sort:'rank',direction:1};
document.querySelector('#date').textContent=D.as_of.slice(0,10);
function options(items,value){return items.map(x=>`<option ${x===value?'selected':''} value="${esc(x)}">${esc(x)}</option>`).join('')}
function badge(r){return watch.has(r.slug)?'<span class="badge">WATCHLIST</span>':''}
function change(n){return n===null?'—':`<span class="${n<0?'down':'up'}">${n>0?'+':''}${num(n)}%</span>`}
function board(){
app.innerHTML=`<div class="intro"><div><div class="eyebrow">01 / OPPORTUNITY BOARD</div><h1>Before the token. Follow the signal.</h1><p>Snapshot candidates that record no token, ranked by comparable implied value.</p></div><span class="tag">RESEARCH ESTIMATES • NOT LAUNCH PREDICTIONS</span></div><div class="stats">${[[D.tracked_size,'Protocols tracked'],[D.board_size,'Pre-token candidates'],[D.comparable_size,'Tokened comparables'],[D.watchlist_size+'/'+D.watchlist_size,'Watchlist covered']].map(([n,l])=>`<div class="stat"><strong>${n}</strong><span class="label">${l}</span></div>`).join('')}</div><div class="method"><b>THE MODEL</b> &nbsp; TVL × category multiple × growth factor × tracking-age factor = implied value.<br>Comparables are winsorized at 1–99%; category medians shrink toward the global median (4-comparable minimum). Growth uses candidate percentiles; age uses years tracked. Records no token means market cap, symbol and Gecko ID are all null.</div><div class="filters"><input id="search" type="search" aria-label="Search protocols" placeholder="Search protocol or slug…" value="${esc(state.q)}"><select id="category" aria-label="Category"><option value="">All categories</option>${options(categories,state.cat)}</select><select id="chain" aria-label="Chain"><option value="">All chains</option>${options(chains,state.chain)}</select><select id="band" aria-label="TVL band"><option value="">All TVL bands</option>${options(['Under $50M','$50M–$100M','$100M–$1B','$1B+'],state.band)}</select><label class="toggle"><input id="watch" type="checkbox" ${state.watch?'checked':''}>Watchlist only</label><button id="reset">Reset</button></div><div class="result"><span id="count"></span><span>SELECT A PROTOCOL TO OPEN ITS RESEARCH PLAN ↗</span></div><div class="table-wrap"><table><thead><tr>${[['rank','#'],['name','Protocol'],['category','Category'],['chains','Chains'],['tvl_usd','TVL'],['change_7d','7D change'],['age_years','Years tracked'],['multiple_used','Cat. multiple'],['implied_value_usd','Implied value'],['sensitivity_low','Sensitivity range']].map(([k,l])=>`<th>${['category','chains'].includes(k)?l:`<button data-sort="${k}">${l} <span>${state.sort===k?(state.direction===1?'↑':'↓'):'↕'}</span></button>`}</th>`).join('')}</tr></thead><tbody></tbody></table></div>`;
const update=()=>rows();
document.querySelector('#search').oninput=e=>{state.q=e.target.value;update()};
document.querySelector('#category').onchange=e=>{state.cat=e.target.value;history.replaceState(null,'',state.cat?'#cat='+encodeURIComponent(state.cat):location.pathname);update()};
for(const [id,key] of [['chain','chain'],['band','band'],['watch','watch']])document.querySelector('#'+id).onchange=e=>{state[key]=id==='watch'?e.target.checked:e.target.value;update()};
document.querySelector('#reset').onclick=()=>{state={q:'',cat:'',chain:'',band:'',watch:false,sort:'rank',direction:1};history.replaceState(null,'',location.pathname);board()};
document.querySelectorAll('[data-sort]').forEach(b=>b.onclick=()=>{const key=b.dataset.sort;state.direction=state.sort===key?-state.direction:key==='name'||key==='rank'?1:-1;state.sort=key;board()});rows();
}
function rows(){const list=D.rows.filter(r=>(!state.q||(r.name+' '+r.slug).toLowerCase().includes(state.q.toLowerCase()))&&(!state.cat||(r.category??'Uncategorized')===state.cat)&&(!state.chain||r.chains.includes(state.chain))&&(!state.watch||watch.has(r.slug))&&(!state.band||(state.band==='Under $50M'?r.tvl_usd<5e7:state.band==='$50M–$100M'?r.tvl_usd>=5e7&&r.tvl_usd<1e8:state.band==='$100M–$1B'?r.tvl_usd>=1e8&&r.tvl_usd<1e9:r.tvl_usd>=1e9))).sort((a,b)=>{const x=a[state.sort],y=b[state.sort];if(x===null)return y===null?a.rank-b.rank:1;if(y===null)return -1;return (typeof x==='string'?x.localeCompare(y):x-y)*state.direction||a.rank-b.rank});
document.querySelector('#count').textContent=`${list.length} OF ${D.board_size} CANDIDATES${state.cat?' / '+state.cat.toUpperCase():''}`;
document.querySelector('tbody').innerHTML=list.length?list.map(r=>`<tr><td>${r.rank.toString().padStart(2,'0')}</td><td><a href="#p=${encodeURIComponent(r.slug)}">${esc(r.name)}</a>${badge(r)}</td><td>${esc(r.category)}</td><td><span class="chains" title="${esc(r.chains.join(', '))}">${esc(r.chains.join(', '))}</span></td><td>${compact(r.tvl_usd)}</td><td>${change(r.change_7d)}</td><td>${num(r.age_years)}</td><td>${num(r.multiple_used,3)}×</td><td>${compact(r.implied_value_usd)}</td><td>${r.sensitivity_low===null||r.sensitivity_high===null?'—':compact(r.sensitivity_low)+' – '+compact(r.sensitivity_high)}</td></tr>`).join(''):'<tr><td colspan="10" class="empty">No candidates match these filters.</td></tr>';
}
function detail(r){const comps=D.live.filter(p=>p.tvl_usd>0&&p.category===r.category).length;app.innerHTML=`<a class="back" href="${state.cat?'#cat='+encodeURIComponent(state.cat):'#'}">← Back to opportunity board</a><div class="detail-head"><div><div class="eyebrow">02 / PROTOCOL RESEARCH · RANK ${r.rank}</div><h1>${esc(r.name)} ${badge(r)}</h1><p>${esc(r.category)} &nbsp; / &nbsp; ${esc(r.chains.join(' · '))}</p></div><div class="value">${money(r.implied_value_usd)}<small>IMPLIED TOKEN VALUE / USD</small></div></div><div class="detail-grid"><section class="panel"><h2>The valuation, unpacked</h2><div class="formula"><span>Snapshot TVL</span><strong>${money(r.tvl_usd)}</strong><span>× Category multiple · ${comps} comparables</span><strong>${num(r.multiple_used,6)}×</strong><span>× Growth factor · 7d ${num(r.change_7d)}%</span><strong>${num(r.growth_factor,6)}×</strong><span>× Age factor · ${num(r.age_years)} years tracked</span><strong>${num(r.age_factor,6)}×</strong><span class="total">= Implied value</span><strong class="total">${money(r.implied_value_usd)}</strong></div><p class="note">Rounded to whole dollars using full-precision factors. ${comps<4?'Fewer than 4 category comparables: global median used.':'Category median shrunk toward the global median with weight n / (n + 4).'} This is a conditional estimate, not a forecast of issuance or a market price.</p><section class="sensitivity"><h2>Sensitivity</h2><p class="note">Snapshot TVL ${money(r.tvl_usd)} × each multiple × the same growth and age factors. Sensitivity estimates, not predictions. Range orders the global and P75 endpoints low to high.</p><div class="sensitivity-strip">${[['Global winsorized median',r.multiple_global,r.implied_at_global],[comps<4?'Used multiple · global fallback':'Used category multiple · shrunk',r.multiple_used,r.implied_value_usd],[r.p75_source==='global'?'Global 75th percentile · fewer than 4 category comps':'Category 75th percentile · unshrunk',r.multiple_p75,r.implied_at_p75]].map(([label,multiple,value])=>`<div><span>${esc(label)}</span><b>${num(multiple,6)}×</b><strong>${money(value)}</strong></div>`).join('')}</div></section><div class="facts">${[['Token record','Records no token'],['First tracked',r.listed_at??'Unreported'],['Snapshot TVL',money(r.tvl_usd)],['7-day TVL change',r.change_7d===null?'Unreported':num(r.change_7d)+'%'],['Category',r.category??'Uncategorized'],['Networks',r.chains.join(', ')||'Unreported']].map(([k,v])=>`<div><span class="label">${k}</span><b>${esc(v)}</b></div>`).join('')}</div><details class="raw"><summary>Full-precision derivation</summary><p>${esc(r.derivation)}</p></details></section><section class="panel"><h2>A small, deliberate participation plan</h2><ol class="plan">${r.farm_steps.map(s=>`<li>${esc(s)}</li>`).join('')}</ol><p class="note">Snapshot-based protocol trial plan. TVL tiers size the trial budget, not safety. Confirm product availability and official terms; rewards are unconfirmed.</p></section></div>`}
function route(){const hash=new URLSearchParams(location.hash.slice(1));if(hash.has('cat'))state.cat=hash.get('cat');else if(!hash.has('p'))state.cat='';const slug=hash.get('p');if(slug){const r=D.rows.find(r=>r.slug===slug);if(r)detail(r);else app.innerHTML='<h1>Protocol not found</h1><a href="#">Return to board</a>'}else board()}
window.addEventListener('hashchange',route);route();
